// /qup-work-app/add-chat-app.mjs
// Adds the chat to the Qup Work app: the conversation screen, the unread badge on the
// Messages tab, "Message customer" on jobs, and the new texts in all 35 languages.
//
// Run it from the qup-work-app folder:
//   node add-chat-app.mjs             → make the changes
//   node add-chat-app.mjs --dry-run   → only show what would change
//
// Every file it replaces is copied to _backup_chat_<time>/ first. Running it twice is safe.
// Afterwards: node scripts/check-locales.mjs, then npx expo start.
import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();
const DRY = process.argv.includes('--dry-run');
const STAMP = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
const BACKUP = path.join(ROOT, `_backup_chat_${STAMP}`);

// Make sure we're in the right project
const pkgFile = path.join(ROOT, 'package.json');
const pkg = fs.existsSync(pkgFile) ? JSON.parse(fs.readFileSync(pkgFile, 'utf8')) : null;
if (pkg?.name !== 'qup-work-app') {
  console.error('❌ Run this from your qup-work-app folder (the one with package.json).');
  process.exit(1);
}

function backup(rel) {
  const from = path.join(ROOT, rel);
  if (!fs.existsSync(from)) return;
  const to = path.join(BACKUP, rel);
  fs.mkdirSync(path.dirname(to), { recursive: true });
  fs.copyFileSync(from, to);
}

// ---------------------------------------------------------------------------
// Files, written in full (new ones are created, changed ones replaced)
// ---------------------------------------------------------------------------
const FILES = {
  "src/app/conversation/[id].js": "// /qup-work-app/src/app/conversation/[id].js\n// One conversation. Newest message at the bottom; scroll up to load older ones.\n// The API has no live connection (yet), so while the screen is open we ask for the\n// latest messages every few seconds (new ones, plus whether yours have been seen).\nimport Ionicons from '@expo/vector-icons/Ionicons';\nimport { router, useFocusEffect, useLocalSearchParams } from 'expo-router';\nimport { useCallback, useMemo, useRef, useState } from 'react';\nimport {\n  ActivityIndicator,\n  AppState,\n  FlatList,\n  KeyboardAvoidingView,\n  Platform,\n  Pressable,\n  StyleSheet,\n  TextInput,\n  View,\n} from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { AppText } from '@/components/AppText';\nimport { Avatar } from '@/components/Avatar';\nimport { BackButton } from '@/components/BackButton';\nimport { ChatBubble } from '@/components/ChatBubble';\nimport { EmptyState } from '@/components/EmptyState';\nimport { ErrorBanner } from '@/components/ErrorBanner';\nimport { FocusStatusBar } from '@/components/FocusStatusBar';\nimport { Loading } from '@/components/Loading';\nimport { SignInPrompt } from '@/components/SignInPrompt';\nimport { StatusBadge } from '@/components/StatusBadge';\nimport { colors, fonts, radius, spacing } from '@/constants/theme';\nimport { useAuth } from '@/context/AuthContext';\nimport { useUnread } from '@/context/UnreadContext';\nimport { api, errorMessage } from '@/lib/api';\nimport { useI18n } from '@/i18n';\nimport { dayLabel, isSameDay } from '@/lib/format';\n\nconst POLL_MS = 4000;\nconst PAGE = 30;\nconst POLL_LIMIT = 20;\nconst GROUP_GAP_MS = 5 * 60 * 1000; // messages closer than this from the same person stick together\nconst MAX_LENGTH = 5000;\n\nexport default function ConversationScreen() {\n  const { id } = useLocalSearchParams();\n  const { user } = useAuth();\n  const { t } = useI18n();\n  const insets = useSafeAreaInsets();\n\n  if (!user) {\n    return (\n      <View style={[styles.screen, { paddingTop: insets.top + spacing.md }]}>\n        <View style={{ paddingHorizontal: spacing.xl }}>\n          <BackButton />\n        </View>\n        <SignInPrompt icon=\"chatbubbles-outline\" title={t('MESSAGES_GUEST_TITLE')} text={t('MESSAGES_GUEST_TEXT')} />\n      </View>\n    );\n  }\n  return <Chat key={id} conversationId={id} userId={user._id} />;\n}\n\nfunction Chat({ conversationId, userId }) {\n  const { t } = useI18n();\n  const insets = useSafeAreaInsets();\n  const { refreshUnread } = useUnread();\n\n  const [conversation, setConversation] = useState(null);\n  // Newest first, which is what the inverted list wants\n  const [messages, setMessages] = useState([]);\n  const [hasMore, setHasMore] = useState(false);\n  const [loadingOlder, setLoadingOlder] = useState(false);\n  const [loadError, setLoadError] = useState(null);\n  const [olderError, setOlderError] = useState(null);\n  const [draft, setDraft] = useState('');\n\n  // The poller and the send handler read these without re-creating the timers\n  const messagesRef = useRef(messages);\n  messagesRef.current = messages;\n\n  const base = `/conversations/${conversationId}`;\n\n  const markRead = useCallback(async () => {\n    try {\n      await api(`${base}/read`, { method: 'POST' });\n      refreshUnread();\n    } catch {\n      // Not worth bothering the user about; it'll be marked next time\n    }\n  }, [base, refreshUnread]);\n\n  // Put messages from the server into the list: no duplicates, newest first, the ones\n  // still on their way at the very top. A message we just sent can come back from the\n  // poll before the POST answers; then the pending copy with the same text is dropped.\n  const merge = useCallback(\n    (incoming) => {\n      if (!incoming.length) return;\n      setMessages((current) => {\n        const byId = new Map(current.filter((m) => m._id).map((m) => [m._id, m]));\n        for (const m of incoming) byId.set(m._id, m);\n        const echoed = new Set(incoming.filter((m) => m.sender?._id === userId).map((m) => m.text));\n        const pending = current.filter((m) => !m._id && !(m.status === 'sending' && echoed.has(m.text)));\n        const saved = [...byId.values()].sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));\n        return [...pending, ...saved];\n      });\n    },\n    [userId]\n  );\n\n  const loadFirst = useCallback(async () => {\n    try {\n      const [conv, page] = await Promise.all([api(base), api(`${base}/messages?limit=${PAGE}`)]);\n      setConversation(conv.conversation);\n      setMessages(page.messages);\n      setHasMore(page.hasMore);\n      setLoadError(null);\n      markRead();\n    } catch (err) {\n      setLoadError(errorMessage(err));\n    }\n  }, [base, markRead]);\n\n  // Fetch the latest few each time: merging them by id also refreshes their \"seen\" state.\n  // If even the oldest of those is new to us, we were away for a while, so fill the gap with ?after=.\n  const poll = useCallback(async () => {\n    const known = new Set(messagesRef.current.filter((m) => m._id).map((m) => m._id));\n    const newest = messagesRef.current.find((m) => m._id);\n    try {\n      let { messages: latest } = await api(`${base}/messages?limit=${POLL_LIMIT}`);\n      const oldestLatest = latest[latest.length - 1];\n      if (newest && latest.length === POLL_LIMIT && !known.has(oldestLatest._id)) {\n        const gap = await api(`${base}/messages?after=${encodeURIComponent(newest.createdAt)}&limit=100`);\n        latest = [...latest, ...gap.messages];\n      }\n      if (!latest.length) return;\n      merge(latest);\n      if (latest.some((m) => !known.has(m._id) && m.sender?._id !== userId)) markRead();\n    } catch {\n      // Offline for a moment; the next tick tries again\n    }\n  }, [base, merge, markRead, userId]);\n\n  // Load when the screen opens, then poll while it's visible and the app is in front\n  useFocusEffect(\n    useCallback(() => {\n      let timer = null;\n      const start = () => {\n        clearInterval(timer);\n        timer = setInterval(poll, POLL_MS);\n      };\n      if (messagesRef.current.length) poll();\n      else loadFirst();\n      start();\n\n      const sub = AppState.addEventListener('change', (state) => {\n        if (state === 'active') {\n          poll();\n          start();\n        } else {\n          clearInterval(timer);\n        }\n      });\n      return () => {\n        clearInterval(timer);\n        sub.remove();\n      };\n    }, [poll, loadFirst])\n  );\n\n  async function loadOlder() {\n    if (!hasMore || loadingOlder) return;\n    const oldest = [...messagesRef.current].reverse().find((m) => m._id);\n    if (!oldest) return;\n    setLoadingOlder(true);\n    setOlderError(null);\n    try {\n      const page = await api(`${base}/messages?before=${encodeURIComponent(oldest.createdAt)}&limit=${PAGE}`);\n      merge(page.messages);\n      setHasMore(page.hasMore);\n    } catch (err) {\n      setOlderError(errorMessage(err));\n    } finally {\n      setLoadingOlder(false);\n    }\n  }\n\n  async function deliver(clientId, text) {\n    try {\n      const res = await api(`${base}/messages`, { method: 'POST', body: { text } });\n      setMessages((current) => current.filter((m) => m.clientId !== clientId));\n      merge([res.message]);\n    } catch {\n      setMessages((current) => current.map((m) => (m.clientId === clientId ? { ...m, status: 'failed' } : m)));\n    }\n  }\n\n  function send() {\n    const text = draft.trim();\n    if (!text) return;\n    const clientId = `local-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;\n    setMessages((current) => [\n      { clientId, text, type: 'text', status: 'sending', createdAt: new Date().toISOString(), sender: { _id: userId } },\n      ...current,\n    ]);\n    setDraft('');\n    deliver(clientId, text);\n  }\n\n  function retry(message) {\n    setMessages((current) => current.map((m) => (m.clientId === message.clientId ? { ...m, status: 'sending' } : m)));\n    deliver(message.clientId, message.text);\n  }\n\n  const other = conversation?.participants?.find((p) => p._id !== userId);\n  const otherId = other?._id;\n\n  // Grouping, day dividers and \"seen\" are worked out once per change, not per row\n  const rows = useMemo(() => {\n    const newestMine = messages.find((m) => m.sender?._id === userId && m._id);\n    return messages.map((m, i) => {\n      const newer = messages[i - 1];\n      const older = messages[i + 1];\n      const senderOf = (x) => (x?.type === 'system' ? 'system' : x?.sender?._id);\n      const sticks = (a, b) =>\n        a &&\n        b &&\n        senderOf(a) === senderOf(b) &&\n        isSameDay(a.createdAt, b.createdAt) &&\n        Math.abs(new Date(a.createdAt) - new Date(b.createdAt)) < GROUP_GAP_MS &&\n        !a.status === !b.status; // a pending message starts its own group so \"Sending…\" shows\n      return {\n        message: m,\n        key: m._id ?? m.clientId,\n        mine: m.sender?._id === userId,\n        firstOfGroup: !sticks(m, older),\n        lastOfGroup: !sticks(m, newer),\n        // Divider above the first message of each day (and above the very first one once all are loaded)\n        day: older ? (isSameDay(m.createdAt, older.createdAt) ? null : dayLabel(m.createdAt)) : hasMore ? null : dayLabel(m.createdAt),\n        seen: Boolean(otherId) && m === newestMine && m.readBy?.some((r) => r.user === otherId),\n      };\n    });\n  }, [messages, userId, otherId, hasMore]);\n\n  if (loadError && !conversation) {\n    return (\n      <View style={[styles.screen, { paddingTop: insets.top + spacing.md }]}>\n        <View style={{ paddingHorizontal: spacing.xl }}>\n          <BackButton />\n        </View>\n        <EmptyState\n          icon=\"chatbubbles-outline\"\n          title={t('CONVERSATION_NOT_FOUND')}\n          text={loadError}\n          actionTitle={t('TRY_AGAIN')}\n          onAction={loadFirst}\n        />\n      </View>\n    );\n  }\n  if (!conversation) return <Loading />;\n\n  const canSend = draft.trim().length > 0;\n\n  return (\n    <View style={styles.screen}>\n      <FocusStatusBar style=\"light\" />\n\n      <View style={[styles.header, { paddingTop: insets.top + spacing.sm }]}>\n        <View style={styles.headerRow}>\n          <BackButton onDark onPress={() => (router.canGoBack() ? router.back() : router.replace('/messages'))} />\n          <Avatar name={other?.name} url={other?.avatarUrl} size={40} />\n          <AppText variant=\"title\" onDark numberOfLines={1} style={{ flex: 1 }} accessibilityRole=\"header\">\n            {other?.name ?? t('UNKNOWN')}\n          </AppText>\n        </View>\n\n        {conversation.job ? (\n          <Pressable\n            onPress={() => router.push({ pathname: '/job/[id]', params: { id: conversation.job._id } })}\n            accessibilityRole=\"link\"\n            accessibilityLabel={t('OPEN_JOB', { title: conversation.job.title })}\n            style={({ pressed }) => [styles.jobStub, pressed && { opacity: 0.8 }]}\n          >\n            <Ionicons name=\"clipboard-outline\" size={16} color={colors.hivis} />\n            <AppText variant=\"smallStrong\" onDark numberOfLines={1} style={{ flex: 1 }}>\n              {conversation.job.title}\n            </AppText>\n            {conversation.job.status ? <StatusBadge status={conversation.job.status} /> : null}\n            <Ionicons name=\"chevron-forward\" size={16} color={colors.textOnDarkMuted} />\n          </Pressable>\n        ) : null}\n      </View>\n\n      <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>\n        <FlatList\n          inverted\n          data={rows}\n          keyExtractor={(r) => r.key}\n          contentContainerStyle={styles.list}\n          keyboardDismissMode=\"interactive\"\n          keyboardShouldPersistTaps=\"handled\"\n          onEndReached={loadOlder}\n          onEndReachedThreshold={0.3}\n          renderItem={({ item }) => (\n            <View>\n              {item.day ? (\n                <View style={styles.day}>\n                  <View style={styles.dayLine} />\n                  <AppText variant=\"caption\" muted style={styles.dayText}>\n                    {item.day}\n                  </AppText>\n                  <View style={styles.dayLine} />\n                </View>\n              ) : null}\n              <ChatBubble\n                message={item.message}\n                mine={item.mine}\n                firstOfGroup={item.firstOfGroup}\n                lastOfGroup={item.lastOfGroup}\n                seen={item.seen}\n                onRetry={() => retry(item.message)}\n              />\n            </View>\n          )}\n          // Inverted: the \"footer\" is at the top, where older messages load\n          ListFooterComponent={\n            loadingOlder ? (\n              <ActivityIndicator color={colors.slate} style={{ marginVertical: spacing.lg }} />\n            ) : olderError ? (\n              <ErrorBanner message={olderError} onRetry={loadOlder} style={{ marginVertical: spacing.md }} />\n            ) : null\n          }\n          ListEmptyComponent={\n            // The inverted list flips its children; flip the empty state back\n            <View style={{ transform: [{ scaleY: -1 }] }}>\n              <EmptyState icon=\"hand-right-outline\" title={t('CHAT_EMPTY_TITLE')} text={t('CHAT_EMPTY_TEXT', { name: other?.name ?? '' })} />\n            </View>\n          }\n        />\n\n        <View style={[styles.composer, { paddingBottom: Math.max(insets.bottom, spacing.md) }]}>\n          <TextInput\n            value={draft}\n            onChangeText={setDraft}\n            placeholder={t('MESSAGE_PLACEHOLDER')}\n            placeholderTextColor={colors.textMuted}\n            multiline\n            maxLength={MAX_LENGTH}\n            style={styles.input}\n            accessibilityLabel={t('MESSAGE_PLACEHOLDER')}\n            // On web, Enter sends and Shift+Enter makes a new line\n            onKeyPress={\n              Platform.OS === 'web'\n                ? (e) => {\n                    if (e.nativeEvent.key === 'Enter' && !e.nativeEvent.shiftKey) {\n                      e.preventDefault();\n                      send();\n                    }\n                  }\n                : undefined\n            }\n          />\n          <Pressable\n            onPress={send}\n            disabled={!canSend}\n            accessibilityRole=\"button\"\n            accessibilityLabel={t('SEND')}\n            accessibilityState={{ disabled: !canSend }}\n            style={({ pressed }) => [styles.send, !canSend && styles.sendDisabled, pressed && { transform: [{ scale: 0.94 }] }]}\n          >\n            <Ionicons name=\"arrow-up\" size={22} color={canSend ? colors.slate : colors.textMuted} />\n          </Pressable>\n        </View>\n      </KeyboardAvoidingView>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  screen: { flex: 1, backgroundColor: colors.concrete },\n  header: { backgroundColor: colors.slate, paddingHorizontal: spacing.lg, paddingBottom: spacing.md, gap: spacing.md },\n  headerRow: { flexDirection: 'row', alignItems: 'center', gap: spacing.md },\n  jobStub: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: spacing.sm,\n    paddingLeft: spacing.md,\n    paddingRight: spacing.sm,\n    paddingVertical: spacing.sm,\n    borderRadius: radius.ticket,\n    backgroundColor: colors.slateRaised,\n    borderLeftWidth: 3,\n    borderLeftColor: colors.hivis,\n  },\n  list: { paddingHorizontal: spacing.lg, paddingVertical: spacing.md, flexGrow: 1 },\n  day: { flexDirection: 'row', alignItems: 'center', gap: spacing.md, marginTop: spacing.xl, marginBottom: spacing.xs },\n  dayLine: { flex: 1, height: StyleSheet.hairlineWidth, backgroundColor: colors.line },\n  dayText: { textTransform: 'uppercase', letterSpacing: 1 },\n  composer: {\n    flexDirection: 'row',\n    alignItems: 'flex-end',\n    gap: spacing.sm,\n    paddingTop: spacing.sm,\n    paddingHorizontal: spacing.lg,\n    backgroundColor: colors.paper,\n    borderTopWidth: StyleSheet.hairlineWidth,\n    borderTopColor: colors.line,\n  },\n  input: {\n    flex: 1,\n    minHeight: 44,\n    maxHeight: 130,\n    paddingHorizontal: spacing.md,\n    paddingTop: 11,\n    paddingBottom: 11,\n    borderRadius: radius.md,\n    backgroundColor: colors.concrete,\n    fontFamily: fonts.regular,\n    fontSize: 16,\n    lineHeight: 22,\n    color: colors.text,\n  },\n  send: {\n    width: 44,\n    height: 44,\n    borderRadius: radius.md,\n    backgroundColor: colors.hivis,\n    alignItems: 'center',\n    justifyContent: 'center',\n  },\n  sendDisabled: { backgroundColor: colors.line },\n});\n",
  "src/components/ChatBubble.js": "// /qup-work-app/src/components/ChatBubble.js\n// One message in a conversation.\n//   mine     → slate bubble on the right; theirs → white on the left with the sender's avatar\n//   first/last of a group (same sender, a few minutes apart) decide spacing, tail and time\n//   status   'sending' | 'failed' for messages that haven't reached the server yet\nimport Ionicons from '@expo/vector-icons/Ionicons';\nimport { Image, Linking, Pressable, StyleSheet, View } from 'react-native';\nimport { AppText } from '@/components/AppText';\nimport { Avatar } from '@/components/Avatar';\nimport { colors, radius, spacing } from '@/constants/theme';\nimport { useI18n } from '@/i18n';\nimport { formatTime } from '@/lib/format';\n\nconst AVATAR = 30;\n\nexport function ChatBubble({ message, mine, firstOfGroup, lastOfGroup, seen, onRetry }) {\n  const { t } = useI18n();\n\n  if (message.type === 'system') {\n    return (\n      <View style={styles.system}>\n        <AppText variant=\"caption\" muted center>\n          {message.text}\n        </AppText>\n      </View>\n    );\n  }\n\n  const failed = message.status === 'failed';\n  const sending = message.status === 'sending';\n  const images = message.attachments?.filter((a) => a.kind === 'image') ?? [];\n  const files = message.attachments?.filter((a) => a.kind !== 'image') ?? [];\n\n  // The corner pointing at the sender is squared off on the last bubble of a group,\n  // like a torn-off ticket stub\n  const tail = lastOfGroup && (mine ? { borderBottomRightRadius: 4 } : { borderBottomLeftRadius: 4 });\n\n  const bubble = (\n    <View style={[styles.bubble, mine ? styles.mine : styles.theirs, tail, sending && { opacity: 0.6 }]}>\n      {images.map((a) => (\n        <Pressable key={a.url} onPress={() => Linking.openURL(a.url)} accessibilityRole=\"imagebutton\" accessibilityLabel={a.name ?? t('ATTACHMENT')}>\n          <Image source={{ uri: a.url }} style={styles.image} />\n        </Pressable>\n      ))}\n      {files.map((a) => (\n        <Pressable key={a.url} onPress={() => Linking.openURL(a.url)} accessibilityRole=\"link\" style={styles.file}>\n          <Ionicons name=\"document-attach-outline\" size={18} color={mine ? colors.hivis : colors.slate} />\n          <AppText variant=\"smallStrong\" color={mine ? colors.textOnDark : colors.text} numberOfLines={1} style={{ flexShrink: 1 }}>\n            {a.name ?? t('ATTACHMENT')}\n          </AppText>\n        </Pressable>\n      ))}\n      {message.text ? (\n        <AppText variant=\"body\" color={mine ? colors.textOnDark : colors.text} selectable>\n          {message.text}\n        </AppText>\n      ) : null}\n    </View>\n  );\n\n  return (\n    <View style={[styles.row, mine && styles.rowMine, { marginTop: firstOfGroup ? spacing.md : 3 }]}>\n      {!mine ? (\n        <View style={styles.avatarSlot}>\n          {lastOfGroup ? <Avatar name={message.sender?.name} url={message.sender?.avatarUrl} size={AVATAR} dark /> : null}\n        </View>\n      ) : null}\n\n      <View style={[styles.column, mine && { alignItems: 'flex-end' }]}>\n        {failed ? (\n          <Pressable onPress={onRetry} accessibilityRole=\"button\" accessibilityHint={t('MESSAGE_RETRY')}>\n            {bubble}\n          </Pressable>\n        ) : (\n          bubble\n        )}\n\n        {failed ? (\n          <View style={styles.meta}>\n            <Ionicons name=\"alert-circle\" size={14} color={colors.danger} />\n            <AppText variant=\"caption\" color={colors.danger}>\n              {t('MESSAGE_FAILED')}\n            </AppText>\n          </View>\n        ) : lastOfGroup ? (\n          <View style={styles.meta}>\n            <AppText variant=\"caption\" muted>\n              {sending ? t('MESSAGE_SENDING') : formatTime(message.createdAt)}\n            </AppText>\n            {seen ? (\n              <>\n                <Ionicons name=\"checkmark-done\" size={14} color={colors.pine} />\n                <AppText variant=\"caption\" color={colors.pine}>\n                  {t('MESSAGE_SEEN')}\n                </AppText>\n              </>\n            ) : null}\n          </View>\n        ) : null}\n      </View>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  row: { flexDirection: 'row', alignItems: 'flex-end', gap: spacing.sm, paddingRight: spacing.xxxl },\n  rowMine: { justifyContent: 'flex-end', paddingRight: 0, paddingLeft: spacing.xxxl + AVATAR },\n  avatarSlot: { width: AVATAR, marginBottom: 20 },\n  column: { flexShrink: 1, gap: 4, alignItems: 'flex-start' },\n  bubble: {\n    borderRadius: radius.lg,\n    paddingHorizontal: 14,\n    paddingVertical: 10,\n    gap: spacing.sm,\n    maxWidth: 520,\n  },\n  mine: { backgroundColor: colors.slate },\n  theirs: { backgroundColor: colors.paper },\n  meta: { flexDirection: 'row', alignItems: 'center', gap: 4, paddingHorizontal: 4 },\n  image: { width: 220, height: 160, borderRadius: radius.md, backgroundColor: colors.line },\n  file: { flexDirection: 'row', alignItems: 'center', gap: spacing.sm },\n  system: {\n    alignSelf: 'center',\n    marginVertical: spacing.md,\n    paddingHorizontal: spacing.md,\n    paddingVertical: 6,\n    borderRadius: radius.pill,\n    backgroundColor: colors.hivisSoft,\n    maxWidth: '85%',\n  },\n});\n",
  "src/context/UnreadContext.js": "// /qup-work-app/src/context/UnreadContext.js\n// Total unread messages, for the badge on the Messages tab.\n//   const { unread, refreshUnread } = useUnread();\n//\n// Checks when you log in, when the app comes back to the foreground, and every\n// 30 seconds while it's open. Call refreshUnread() after reading a conversation\n// so the badge drops straight away.\nimport { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';\nimport { AppState } from 'react-native';\nimport { useAuth } from '@/context/AuthContext';\nimport { api } from '@/lib/api';\n\nconst POLL_MS = 30000;\nconst UnreadContext = createContext({ unread: 0, refreshUnread: () => {} });\n\nexport function UnreadProvider({ children }) {\n  const { user } = useAuth();\n  const userId = user?._id;\n  const [unread, setUnread] = useState(0);\n\n  const refreshUnread = useCallback(async () => {\n    if (!userId) return;\n    try {\n      const res = await api('/conversations/unread');\n      setUnread(res.unread);\n    } catch {\n      // Offline or a hiccup: keep the last number, try again on the next tick\n    }\n  }, [userId]);\n\n  useEffect(() => {\n    if (!userId) {\n      setUnread(0);\n      return undefined;\n    }\n    refreshUnread();\n    let timer = setInterval(refreshUnread, POLL_MS);\n\n    // Don't poll in the background; check right away when the user comes back\n    const sub = AppState.addEventListener('change', (state) => {\n      clearInterval(timer);\n      if (state === 'active') {\n        refreshUnread();\n        timer = setInterval(refreshUnread, POLL_MS);\n      }\n    });\n    return () => {\n      clearInterval(timer);\n      sub.remove();\n    };\n  }, [userId, refreshUnread]);\n\n  const value = useMemo(() => ({ unread, refreshUnread }), [unread, refreshUnread]);\n  return <UnreadContext.Provider value={value}>{children}</UnreadContext.Provider>;\n}\n\nexport const useUnread = () => useContext(UnreadContext);\n",
  "src/app/_layout.js": "// /qup-work-app/src/app/_layout.js\n// Root of the app. Browsing is open to everyone; login/register open as a modal\n// on top of whatever you were looking at, and close again when you're logged in.\nimport {\n  Archivo_400Regular,\n  Archivo_500Medium,\n  Archivo_600SemiBold,\n  Archivo_700Bold,\n  Archivo_800ExtraBold,\n  useFonts,\n} from '@expo-google-fonts/archivo';\nimport { Stack } from 'expo-router';\nimport { StatusBar } from 'expo-status-bar';\nimport { Loading } from '@/components/Loading';\nimport { colors } from '@/constants/theme';\nimport { AuthProvider, useAuth } from '@/context/AuthContext';\nimport { UnreadProvider } from '@/context/UnreadContext';\nimport { I18nProvider, useI18n } from '@/i18n';\n\n// The tabs are always the bottom of the stack. Even if the app opens on /login\n// (Expo restores the last screen while developing), Utforsk is underneath and\n// login is just a sheet you can close.\nexport const unstable_settings = { initialRouteName: '(tabs)' };\n\nfunction RootNavigator({ fontsReady }) {\n  const { isLoading } = useAuth();\n  const { ready: languageReady } = useI18n();\n  // Wait for the saved language too, so the app never flashes in English first\n  if (!fontsReady || isLoading || !languageReady) return <Loading dark />;\n\n  return (\n    <Stack screenOptions={{ headerShown: false, contentStyle: { backgroundColor: colors.concrete } }}>\n      <Stack.Screen name=\"(tabs)\" />\n      <Stack.Screen name=\"job/[id]\" />\n      <Stack.Screen name=\"pro/[id]\" />\n      <Stack.Screen name=\"my-jobs\" />\n      <Stack.Screen name=\"new-job\" />\n      <Stack.Screen name=\"language\" />\n      <Stack.Screen name=\"conversation/[id]\" />\n      <Stack.Screen name=\"offer/[jobId]\" options={{ presentation: 'modal' }} />\n      <Stack.Screen name=\"(auth)\" options={{ presentation: 'modal' }} />\n    </Stack>\n  );\n}\n\nexport default function RootLayout() {\n  const [fontsLoaded, fontError] = useFonts({\n    Archivo_400Regular,\n    Archivo_500Medium,\n    Archivo_600SemiBold,\n    Archivo_700Bold,\n    Archivo_800ExtraBold,\n  });\n\n  return (\n    <I18nProvider>\n      <AuthProvider>\n        <UnreadProvider>\n          <StatusBar style=\"dark\" />\n          {/* If the fonts fail to load, carry on with the system font rather than hang */}\n          <RootNavigator fontsReady={fontsLoaded || Boolean(fontError)} />\n        </UnreadProvider>\n      </AuthProvider>\n    </I18nProvider>\n  );\n}\n",
  "src/app/(tabs)/_layout.js": "// /qup-work-app/src/app/(tabs)/_layout.js\n// Bottom tabs. Utforsk, Oppdrag and Fagfolk are open to everyone.\nimport Ionicons from '@expo/vector-icons/Ionicons';\nimport { Tabs } from 'expo-router';\nimport { colors, fonts } from '@/constants/theme';\nimport { useUnread } from '@/context/UnreadContext';\nimport { useI18n } from '@/i18n';\n\nconst icon =\n  (name) =>\n  ({ color, focused, size }) => <Ionicons name={focused ? name : `${name}-outline`} color={color} size={size} />;\n\nexport default function TabsLayout() {\n  const { t } = useI18n();\n  const { unread } = useUnread();\n  return (\n    <Tabs\n      screenOptions={{\n        headerShown: false,\n        tabBarActiveTintColor: colors.hivis,\n        tabBarInactiveTintColor: colors.textOnDarkMuted,\n        tabBarStyle: { backgroundColor: colors.slate, borderTopWidth: 0 },\n        tabBarLabelStyle: { fontFamily: fonts.semibold, fontSize: 11 },\n        sceneStyle: { backgroundColor: colors.concrete },\n      }}\n    >\n      <Tabs.Screen name=\"index\" options={{ title: t('TAB_EXPLORE'), tabBarIcon: icon('compass') }} />\n      <Tabs.Screen name=\"jobs\" options={{ title: t('TAB_JOBS'), tabBarIcon: icon('clipboard') }} />\n      <Tabs.Screen name=\"pros\" options={{ title: t('TAB_PROS'), tabBarIcon: icon('people') }} />\n      <Tabs.Screen\n        name=\"messages\"\n        options={{\n          title: t('TAB_MESSAGES'),\n          tabBarIcon: icon('chatbubbles'),\n          tabBarBadge: unread > 0 ? (unread > 99 ? '99+' : unread) : undefined,\n          tabBarBadgeStyle: { backgroundColor: colors.hivis, color: colors.slate, fontFamily: fonts.bold, fontSize: 11 },\n        }}\n      />\n      <Tabs.Screen name=\"profile\" options={{ title: t('TAB_PROFILE'), tabBarIcon: icon('person-circle') }} />\n    </Tabs>\n  );\n}\n",
  "src/app/(tabs)/messages.js": "// /qup-work-app/src/app/(tabs)/messages.js\n// Inbox. Needs an account. Tap a conversation to open it.\nimport { router, useFocusEffect } from 'expo-router';\nimport { useCallback, useState } from 'react';\nimport { FlatList, Pressable, StyleSheet, View } from 'react-native';\nimport { AppText } from '@/components/AppText';\nimport { Avatar } from '@/components/Avatar';\nimport { EmptyState } from '@/components/EmptyState';\nimport { ErrorBanner } from '@/components/ErrorBanner';\nimport { FocusStatusBar } from '@/components/FocusStatusBar';\nimport { Loading } from '@/components/Loading';\nimport { ScreenHeader } from '@/components/ScreenHeader';\nimport { SignInPrompt } from '@/components/SignInPrompt';\nimport { colors, radius, spacing } from '@/constants/theme';\nimport { useAuth } from '@/context/AuthContext';\nimport { useUnread } from '@/context/UnreadContext';\nimport { api, errorMessage } from '@/lib/api';\nimport { useI18n } from '@/i18n';\nimport { timeAgo } from '@/lib/format';\n\nexport default function MessagesScreen() {\n  const { user } = useAuth();\n  const { t } = useI18n();\n\n  if (!user) {\n    return (\n      <View style={styles.screen}>\n        <FocusStatusBar style=\"dark\" />\n        <ScreenHeader title={t('TAB_MESSAGES')} />\n        <SignInPrompt\n          icon=\"chatbubbles-outline\"\n          title={t('MESSAGES_GUEST_TITLE')}\n          text={t('MESSAGES_GUEST_TEXT')}\n        />\n      </View>\n    );\n  }\n  return <Inbox userId={user._id} />;\n}\n\nfunction Inbox({ userId }) {\n  const { t } = useI18n();\n  const { refreshUnread } = useUnread();\n  const [conversations, setConversations] = useState([]);\n  const [loading, setLoading] = useState(true);\n  const [refreshing, setRefreshing] = useState(false);\n  const [error, setError] = useState(null);\n\n  const load = useCallback(async () => {\n    try {\n      const res = await api('/conversations?limit=50');\n      setConversations(res.data);\n      setError(null);\n      refreshUnread();\n    } catch (err) {\n      setError(errorMessage(err));\n    }\n  }, [refreshUnread]);\n\n  useFocusEffect(\n    useCallback(() => {\n      load().finally(() => setLoading(false));\n    }, [load])\n  );\n\n  async function onRefresh() {\n    setRefreshing(true);\n    await load();\n    setRefreshing(false);\n  }\n\n  return (\n    <View style={styles.screen}>\n      <FocusStatusBar style=\"dark\" />\n      <ScreenHeader title={t('TAB_MESSAGES')} />\n      {loading ? (\n        <Loading />\n      ) : (\n        <FlatList\n          data={conversations}\n          keyExtractor={(c) => c._id}\n          contentContainerStyle={styles.list}\n          refreshing={refreshing}\n          onRefresh={onRefresh}\n          ItemSeparatorComponent={() => <View style={{ height: spacing.sm }} />}\n          ListHeaderComponent={error ? <ErrorBanner message={error} onRetry={load} style={{ marginBottom: spacing.md }} /> : null}\n          ListEmptyComponent={\n            error ? null : (\n              <EmptyState icon=\"chatbubbles-outline\" title={t('NO_MESSAGES')} text={t('NO_MESSAGES_TEXT')} />\n            )\n          }\n          renderItem={({ item }) => <ConversationRow conversation={item} userId={userId} />}\n        />\n      )}\n    </View>\n  );\n}\n\nfunction ConversationRow({ conversation, userId }) {\n  const { t } = useI18n();\n  const other = conversation.participants.find((p) => p._id !== userId);\n  const unread = conversation.unread > 0;\n\n  return (\n    <Pressable\n      onPress={() => router.push({ pathname: '/conversation/[id]', params: { id: conversation._id } })}\n      style={({ pressed }) => [styles.row, pressed && { opacity: 0.8 }]}\n      accessibilityRole=\"button\"\n    >\n      <Avatar name={other?.name} url={other?.avatarUrl} size={48} dark={!unread} />\n      <View style={styles.body}>\n        <View style={styles.rowTop}>\n          <AppText variant={unread ? 'title' : 'bodyStrong'} numberOfLines={1} style={{ flex: 1 }}>\n            {other?.name ?? t('UNKNOWN')}\n          </AppText>\n          <AppText variant=\"caption\" muted>\n            {timeAgo(conversation.lastMessage?.sentAt ?? conversation.updatedAt)}\n          </AppText>\n        </View>\n        {conversation.job ? (\n          <AppText variant=\"caption\" muted numberOfLines={1}>\n            {conversation.job.title}\n          </AppText>\n        ) : null}\n        <View style={styles.rowTop}>\n          <AppText variant={unread ? 'smallStrong' : 'small'} muted={!unread} numberOfLines={1} style={{ flex: 1 }}>\n            {conversation.lastMessage?.text ?? ''}\n          </AppText>\n          {unread ? (\n            <View style={styles.badge}>\n              <AppText variant=\"caption\" color={colors.slate}>\n                {conversation.unread}\n              </AppText>\n            </View>\n          ) : null}\n        </View>\n      </View>\n    </Pressable>\n  );\n}\n\nconst styles = StyleSheet.create({\n  screen: { flex: 1, backgroundColor: colors.concrete },\n  list: { padding: spacing.xl, paddingTop: spacing.sm, flexGrow: 1 },\n  row: {\n    flexDirection: 'row',\n    gap: spacing.md,\n    padding: spacing.md,\n    backgroundColor: colors.paper,\n    borderRadius: radius.lg,\n  },\n  body: { flex: 1, gap: 2 },\n  rowTop: { flexDirection: 'row', alignItems: 'center', gap: spacing.sm },\n  badge: {\n    minWidth: 22,\n    height: 22,\n    borderRadius: radius.pill,\n    backgroundColor: colors.hivis,\n    alignItems: 'center',\n    justifyContent: 'center',\n    paddingHorizontal: 6,\n  },\n});\n",
  "src/app/job/[id].js": "// /qup-work-app/src/app/job/[id].js\n// One job as a big work-order ticket. Public for open jobs; acting on it needs an account.\nimport Ionicons from '@expo/vector-icons/Ionicons';\nimport { router, useFocusEffect, useLocalSearchParams } from 'expo-router';\nimport { useCallback, useState } from 'react';\nimport { ScrollView, StyleSheet, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { AppText } from '@/components/AppText';\nimport { Avatar } from '@/components/Avatar';\nimport { BackButton } from '@/components/BackButton';\nimport { BottomBar } from '@/components/BottomBar';\nimport { Button } from '@/components/Button';\nimport { EmptyState } from '@/components/EmptyState';\nimport { ErrorBanner } from '@/components/ErrorBanner';\nimport { FocusStatusBar } from '@/components/FocusStatusBar';\nimport { Loading } from '@/components/Loading';\nimport { Perforation } from '@/components/Perforation';\nimport { StatusBadge } from '@/components/StatusBadge';\nimport { colors, radius, spacing } from '@/constants/theme';\nimport { useAuth } from '@/context/AuthContext';\nimport { api, errorMessage } from '@/lib/api';\nimport { useI18n } from '@/i18n';\nimport { budgetText, categoryIcon, categoryName, formatDate, placeText, timeAgo, URGENCY } from '@/lib/format';\n\nexport default function JobScreen() {\n  const { id } = useLocalSearchParams();\n  const insets = useSafeAreaInsets();\n  const { user, isPro } = useAuth();\n  const { t } = useI18n();\n  const [data, setData] = useState(null);\n  const [error, setError] = useState(null);\n\n  // Reload when coming back from the offer form or login\n  useFocusEffect(\n    useCallback(() => {\n      let alive = true;\n      api(`/jobs/${id}`)\n        .then((res) => alive && (setData(res), setError(null)))\n        .catch((err) => alive && setError(errorMessage(err)));\n      return () => {\n        alive = false;\n      };\n    }, [id, user?._id])\n  );\n\n  if (error && !data) {\n    return (\n      <View style={[styles.screen, { paddingTop: insets.top + spacing.md, paddingHorizontal: spacing.xl }]}>\n        <BackButton />\n        <EmptyState icon=\"clipboard-outline\" title={t('JOB_NOT_FOUND')} text={error} />\n      </View>\n    );\n  }\n  if (!data) return <Loading dark />;\n\n  const { job, side, myOfferStatus } = data;\n  const facts = [\n    job.timing?.urgency && { icon: 'calendar-outline', label: t('FACT_WHEN'), value: t(URGENCY[job.timing.urgency]) },\n    job.timing?.preferredStart && { icon: 'play-outline', label: t('FACT_PREFERRED_START'), value: formatDate(job.timing.preferredStart) },\n    {\n      icon: job.workType === 'remote' ? 'globe-outline' : 'location-outline',\n      label: job.workType === 'remote' ? t('FACT_WORKPLACE') : t('FACT_PLACE'),\n      value: job.workType === 'remote' ? t('REMOTE_WORK') : [job.address?.postalCode, placeText(job)].filter(Boolean).join(' '),\n    },\n    job.address?.line1 && { icon: 'home-outline', label: t('FACT_ADDRESS'), value: job.address.line1 },\n    { icon: 'document-text-outline', label: t('FACT_OFFERS'), value: job.offerCount ? t('OFFERS_RECEIVED', { n: job.offerCount }) : t('NONE_YET') },\n  ].filter(Boolean);\n\n  return (\n    <View style={styles.screen}>\n      <FocusStatusBar style=\"light\" />\n      <ScrollView contentContainerStyle={{ paddingBottom: spacing.xxl }}>\n        <View style={[styles.hero, { paddingTop: insets.top + spacing.md }]}>\n          <BackButton onDark />\n          {job.category ? (\n            <View style={styles.category}>\n              <View style={styles.categoryIcon}>\n                <Ionicons name={categoryIcon(job.category.icon)} size={15} color={colors.slate} />\n              </View>\n              <AppText variant=\"smallStrong\" onDark muted>\n                {categoryName(job.category)}\n              </AppText>\n            </View>\n          ) : null}\n          <AppText variant=\"h1\" onDark accessibilityRole=\"header\">\n            {job.title}\n          </AppText>\n          <AppText variant=\"small\" onDark muted>\n            {t('POSTED_AGO', { time: timeAgo(job.publishedAt ?? job.createdAt) })}\n          </AppText>\n        </View>\n\n        {/* The ticket */}\n        <View style={styles.ticket}>\n          <View style={styles.ticketTop}>\n            <View style={{ flex: 1, gap: 2 }}>\n              <AppText variant=\"caption\" muted>\n                {t('BUDGET')}\n              </AppText>\n              <AppText variant=\"h2\">{budgetText(job.budget)}</AppText>\n            </View>\n            <StatusBadge status={job.status} />\n          </View>\n\n          <Perforation notchColor={colors.concrete} />\n\n          <View style={styles.facts}>\n            {facts.map((f) => (\n              <View key={f.label} style={styles.fact}>\n                <Ionicons name={f.icon} size={18} color={colors.textMuted} />\n                <AppText variant=\"small\" muted style={styles.factLabel}>\n                  {f.label}\n                </AppText>\n                <AppText variant=\"smallStrong\" style={{ flex: 1, textAlign: 'right' }}>\n                  {f.value}\n                </AppText>\n              </View>\n            ))}\n          </View>\n        </View>\n\n        {job.description ? (\n          <View style={styles.section}>\n            <AppText variant=\"title\">{t('DESCRIPTION')}</AppText>\n            <AppText variant=\"body\">{job.description}</AppText>\n          </View>\n        ) : null}\n\n        {job.customer ? (\n          <View style={[styles.section, styles.person]}>\n            <Avatar name={job.customer.name} url={job.customer.avatarUrl} size={44} dark />\n            <View>\n              <AppText variant=\"caption\" muted>\n                {t('POSTED_BY')}\n              </AppText>\n              <AppText variant=\"bodyStrong\">{job.customer.name}</AppText>\n            </View>\n          </View>\n        ) : null}\n\n        {side === 'guest' || side === 'viewer' ? (\n          <AppText variant=\"small\" muted style={styles.privacy}>\n            {t('ADDRESS_PRIVACY_NOTE')}\n          </AppText>\n        ) : null}\n      </ScrollView>\n\n      <JobActions job={job} side={side} myOfferStatus={myOfferStatus} isPro={isPro} />\n    </View>\n  );\n}\n\n// Opens (or creates) the conversation with the customer about this job\nfunction MessageCustomerButton({ job, variant = 'outline' }) {\n  const { t } = useI18n();\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState(null);\n  if (!job.customer?._id) return null;\n\n  async function open() {\n    setBusy(true);\n    setError(null);\n    try {\n      const res = await api('/conversations', {\n        method: 'POST',\n        body: { participant: job.customer._id, job: job._id },\n      });\n      router.push({ pathname: '/conversation/[id]', params: { id: res.conversation._id } });\n    } catch (err) {\n      setError(errorMessage(err));\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <>\n      <ErrorBanner message={error} />\n      <Button\n        title={t('MESSAGE_CUSTOMER', { name: job.customer.name })}\n        icon=\"chatbubble-outline\"\n        variant={variant}\n        loading={busy}\n        onPress={open}\n      />\n    </>\n  );\n}\n\n// What the button at the bottom does depends on who's looking\nfunction JobActions({ job, side, myOfferStatus, isPro }) {\n  const { t } = useI18n();\n  if (side === 'guest') {\n    return (\n      <BottomBar>\n        <Button title={t('LOG_IN_TO_OFFER')} variant=\"dark\" onPress={() => router.push('/login')} />\n      </BottomBar>\n    );\n  }\n\n  if (side === 'viewer') {\n    if (myOfferStatus) {\n      return (\n        <BottomBar>\n          <View style={styles.note}>\n            <Ionicons name=\"checkmark-circle\" size={20} color={colors.pine} />\n            <AppText variant=\"bodyStrong\" color={colors.pine}>\n              {t('OFFER_ALREADY_SENT')}\n            </AppText>\n          </View>\n          <MessageCustomerButton job={job} />\n        </BottomBar>\n      );\n    }\n    if (!isPro) {\n      return (\n        <BottomBar>\n          <AppText variant=\"small\" muted center>\n            {t('ONLY_PROS_CAN_OFFER')}\n          </AppText>\n        </BottomBar>\n      );\n    }\n    return (\n      <BottomBar>\n        <Button\n          title={t('MAKE_OFFER')}\n          icon=\"document-text-outline\"\n          onPress={() => router.push({ pathname: '/offer/[jobId]', params: { jobId: job._id, title: job.title } })}\n        />\n      </BottomBar>\n    );\n  }\n\n  // The pro doing the job\n  if (side === 'pro') {\n    return (\n      <BottomBar>\n        <MessageCustomerButton job={job} variant=\"dark\" />\n      </BottomBar>\n    );\n  }\n\n  if (side === 'customer') {\n    return (\n      <BottomBar>\n        <AppText variant=\"small\" muted center>\n          {job.offerCount ? t('CUSTOMER_OFFERS_RECEIVED', { n: job.offerCount }) : t('CUSTOMER_WAITING_FOR_OFFERS')}\n        </AppText>\n      </BottomBar>\n    );\n  }\n\n  return null;\n}\n\nconst styles = StyleSheet.create({\n  screen: { flex: 1, backgroundColor: colors.concrete },\n  hero: {\n    backgroundColor: colors.slate,\n    paddingHorizontal: spacing.xl,\n    paddingBottom: spacing.xxxl + spacing.lg, // room for the ticket to overlap\n    gap: spacing.md,\n  },\n  category: { flexDirection: 'row', alignItems: 'center', gap: spacing.sm, marginTop: spacing.sm },\n  categoryIcon: {\n    width: 24,\n    height: 24,\n    borderRadius: 5,\n    backgroundColor: colors.hivis,\n    alignItems: 'center',\n    justifyContent: 'center',\n  },\n  ticket: {\n    marginTop: -spacing.xxxl,\n    marginHorizontal: spacing.xl,\n    backgroundColor: colors.paper,\n    borderRadius: radius.ticket,\n  },\n  ticketTop: { flexDirection: 'row', alignItems: 'center', gap: spacing.md, padding: spacing.lg },\n  facts: { padding: spacing.lg, paddingTop: spacing.sm, gap: spacing.md },\n  fact: { flexDirection: 'row', alignItems: 'center', gap: spacing.sm },\n  factLabel: { width: 118 },\n  section: { marginTop: spacing.xxl, marginHorizontal: spacing.xl, gap: spacing.sm, maxWidth: 640 },\n  person: { flexDirection: 'row', alignItems: 'center', gap: spacing.md },\n  privacy: { marginTop: spacing.xl, marginHorizontal: spacing.xl },\n  note: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: spacing.sm, minHeight: 44 },\n});\n",
  "src/app/pro/[id].js": "// /qup-work-app/src/app/pro/[id].js\n// Public profile of a pro (id = the pro's user id).\nimport Ionicons from '@expo/vector-icons/Ionicons';\nimport { router, useLocalSearchParams } from 'expo-router';\nimport { useEffect, useState } from 'react';\nimport { ScrollView, StyleSheet, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { AppText } from '@/components/AppText';\nimport { Avatar } from '@/components/Avatar';\nimport { BackButton } from '@/components/BackButton';\nimport { BottomBar } from '@/components/BottomBar';\nimport { Button } from '@/components/Button';\nimport { EmptyState } from '@/components/EmptyState';\nimport { ErrorBanner } from '@/components/ErrorBanner';\nimport { FocusStatusBar } from '@/components/FocusStatusBar';\nimport { Loading } from '@/components/Loading';\nimport { Rating } from '@/components/Rating';\nimport { colors, radius, spacing } from '@/constants/theme';\nimport { useAuth } from '@/context/AuthContext';\nimport { api, errorMessage } from '@/lib/api';\nimport { useI18n } from '@/i18n';\nimport { categoryIcon, categoryName, formatDate, formatNok } from '@/lib/format';\nimport { useRequireLogin } from '@/lib/useRequireLogin';\n\nexport default function ProScreen() {\n  const { id } = useLocalSearchParams();\n  const insets = useSafeAreaInsets();\n  const { user } = useAuth();\n  const { t } = useI18n();\n  const requireLogin = useRequireLogin();\n  const [data, setData] = useState(null);\n  const [error, setError] = useState(null);\n  const [sending, setSending] = useState(false);\n  const [actionError, setActionError] = useState(null);\n\n  useEffect(() => {\n    api(`/pros/${id}`)\n      .then(setData)\n      .catch((err) => setError(errorMessage(err)));\n  }, [id]);\n\n  if (error) {\n    return (\n      <View style={[styles.screen, { paddingTop: insets.top + spacing.md, paddingHorizontal: spacing.xl }]}>\n        <BackButton />\n        <EmptyState icon=\"person-outline\" title={t('PROFILE_NOT_FOUND')} text={error} />\n      </View>\n    );\n  }\n  if (!data) return <Loading dark />;\n\n  const { profile, reviews } = data;\n  const name = profile.company?.name ?? profile.user?.name;\n  const isMe = user?._id === profile.user?._id;\n  const area = profile.serviceArea;\n\n  async function contact() {\n    setSending(true);\n    setActionError(null);\n    try {\n      const res = await api('/conversations', { method: 'POST', body: { participant: profile.user._id } });\n      router.push({ pathname: '/conversation/[id]', params: { id: res.conversation._id } });\n    } catch (err) {\n      setActionError(errorMessage(err));\n    } finally {\n      setSending(false);\n    }\n  }\n\n  return (\n    <View style={styles.screen}>\n      <FocusStatusBar style=\"light\" />\n      <ScrollView contentContainerStyle={{ paddingBottom: spacing.xxl }}>\n        <View style={[styles.hero, { paddingTop: insets.top + spacing.md }]}>\n          <BackButton onDark />\n          <View style={styles.identity}>\n            <Avatar name={name} url={profile.company?.logoUrl ?? profile.user?.avatarUrl} size={76} />\n            <View style={{ flex: 1, gap: 4 }}>\n              <AppText variant=\"h1\" onDark accessibilityRole=\"header\">\n                {name}\n              </AppText>\n              {profile.company && profile.user?.name ? (\n                <AppText variant=\"small\" onDark muted>\n                  {profile.user.name}\n                </AppText>\n              ) : null}\n              <Rating avg={profile.stats?.ratingAvg} count={profile.stats?.ratingCount} onDark />\n            </View>\n          </View>\n\n          {profile.verification?.orgNumberVerified ? (\n            <View style={styles.verified}>\n              <Ionicons name=\"shield-checkmark\" size={16} color={colors.hivis} />\n              <AppText variant=\"smallStrong\" onDark>\n                {t('VERIFIED_BRREG')}\n              </AppText>\n            </View>\n          ) : null}\n\n          <View style={styles.stats}>\n            <Stat value={String(profile.stats?.completedJobs ?? 0)} label={t('STAT_COMPLETED_JOBS')} />\n            <Stat value={profile.hourlyRate ? formatNok(profile.hourlyRate) : '–'} label={t('STAT_HOURLY_RATE_FROM')} />\n            <Stat value={area?.radiusKm ? `${area.radiusKm} km` : '–'} label={t('STAT_COVERS')} />\n          </View>\n        </View>\n\n        <View style={styles.body}>\n          {profile.headline || profile.bio ? (\n            <View style={styles.section}>\n              {profile.headline ? <AppText variant=\"title\">{profile.headline}</AppText> : null}\n              {profile.bio ? <AppText variant=\"body\">{profile.bio}</AppText> : null}\n            </View>\n          ) : null}\n\n          {profile.categories?.length ? (\n            <View style={styles.section}>\n              <AppText variant=\"title\">{t('SPECIALTIES')}</AppText>\n              <View style={styles.tags}>\n                {profile.categories.map((c) => (\n                  <View key={c._id} style={styles.tag}>\n                    <Ionicons name={categoryIcon(c.icon)} size={15} color={colors.slate} />\n                    <AppText variant=\"smallStrong\">{categoryName(c)}</AppText>\n                  </View>\n                ))}\n              </View>\n            </View>\n          ) : null}\n\n          {area?.municipalities?.length ? (\n            <View style={styles.section}>\n              <AppText variant=\"title\">{t('SERVICE_AREA')}</AppText>\n              <AppText variant=\"body\">{area.municipalities.join(', ')}</AppText>\n            </View>\n          ) : null}\n\n          <View style={styles.section}>\n            <AppText variant=\"title\">{t('REVIEWS')}</AppText>\n            {reviews?.length ? (\n              reviews.map((r) => <Review key={r._id} review={r} />)\n            ) : (\n              <AppText variant=\"small\" muted>\n                {t('NO_REVIEWS')}\n              </AppText>\n            )}\n          </View>\n        </View>\n      </ScrollView>\n\n      {!isMe ? (\n        <BottomBar>\n          <ErrorBanner message={actionError} />\n          <Button\n            title={user ? t('SEND_MESSAGE') : t('LOG_IN_TO_MESSAGE')}\n            icon=\"chatbubble-outline\"\n            variant={user ? 'primary' : 'dark'}\n            loading={sending}\n            onPress={() => requireLogin(contact)}\n          />\n        </BottomBar>\n      ) : null}\n    </View>\n  );\n}\n\nfunction Stat({ value, label }) {\n  return (\n    <View style={{ flex: 1, gap: 2 }}>\n      <AppText variant=\"title\" onDark>\n        {value}\n      </AppText>\n      <AppText variant=\"caption\" onDark muted>\n        {label}\n      </AppText>\n    </View>\n  );\n}\n\nfunction Review({ review }) {\n  const { t } = useI18n();\n  return (\n    <View style={styles.review}>\n      <View style={styles.reviewTop}>\n        <Avatar name={review.reviewer?.name} url={review.reviewer?.avatarUrl} size={36} dark />\n        <View style={{ flex: 1 }}>\n          <AppText variant=\"smallStrong\">{review.reviewer?.name ?? t('CUSTOMER')}</AppText>\n          <AppText variant=\"caption\" muted>\n            {formatDate(review.createdAt)}\n          </AppText>\n        </View>\n        <View style={styles.stars} accessibilityLabel={t('RATING_OUT_OF_5', { n: review.rating })}>\n          {[1, 2, 3, 4, 5].map((n) => (\n            <Ionicons key={n} name={n <= review.rating ? 'star' : 'star-outline'} size={14} color={colors.hivisDeep} />\n          ))}\n        </View>\n      </View>\n      {review.comment ? <AppText variant=\"body\">{review.comment}</AppText> : null}\n      {review.reply?.text ? (\n        <View style={styles.reply}>\n          <AppText variant=\"caption\" muted>\n            {t('REPLY_FROM_PRO')}\n          </AppText>\n          <AppText variant=\"small\">{review.reply.text}</AppText>\n        </View>\n      ) : null}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  screen: { flex: 1, backgroundColor: colors.concrete },\n  hero: { backgroundColor: colors.slate, padding: spacing.xl, gap: spacing.lg },\n  identity: { flexDirection: 'row', alignItems: 'center', gap: spacing.lg },\n  verified: { flexDirection: 'row', alignItems: 'center', gap: 6 },\n  stats: {\n    flexDirection: 'row',\n    gap: spacing.md,\n    paddingTop: spacing.lg,\n    borderTopWidth: StyleSheet.hairlineWidth,\n    borderTopColor: colors.slateLine,\n  },\n  body: { padding: spacing.xl, gap: spacing.xxl },\n  section: { gap: spacing.sm, maxWidth: 640 },\n  tags: { flexDirection: 'row', flexWrap: 'wrap', gap: spacing.sm },\n  tag: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: 6,\n    paddingHorizontal: 12,\n    height: 34,\n    borderRadius: radius.pill,\n    backgroundColor: colors.paper,\n  },\n  review: { backgroundColor: colors.paper, borderRadius: radius.lg, padding: spacing.lg, gap: spacing.sm },\n  reviewTop: { flexDirection: 'row', alignItems: 'center', gap: spacing.md },\n  stars: { flexDirection: 'row', gap: 1 },\n  reply: { borderLeftWidth: 3, borderLeftColor: colors.hivis, paddingLeft: spacing.md, gap: 2 },\n});\n",
  "src/lib/format.js": "// /qup-work-app/src/lib/format.js\n// Formatting helpers. Text comes from the translation files via translate(),\n// so they follow the chosen language.\nimport Ionicons from '@expo/vector-icons/Ionicons';\nimport { colors } from '@/constants/theme';\nimport { currentLocale, hasTranslation, translate as t } from '@/i18n';\n\n// 125000 øre → \"1 250 kr\"   (the marketplace is in NOK; shows øre only when there are any)\nexport function formatNok(ore) {\n  if (ore == null) return '';\n  const negative = ore < 0;\n  const abs = Math.abs(Math.round(ore));\n  const kroner = Math.floor(abs / 100);\n  const rest = abs % 100;\n  const withSpaces = String(kroner).replace(/\\B(?=(\\d{3})+(?!\\d))/g, ' ');\n  const decimals = rest ? `,${String(rest).padStart(2, '0')}` : '';\n  return `${negative ? '−' : ''}${withSpaces}${decimals} kr`;\n}\n\n// Budget on a job: \"5 000–10 000 kr\", \"Up to 8 000 kr\", \"From 2 000 kr\" or \"Price by agreement\"\nexport function budgetText(budget) {\n  const min = budget?.min;\n  const max = budget?.max;\n  if (min != null && max != null) {\n    return t('BUDGET_RANGE', { min: formatNok(min).replace(' kr', ''), max: formatNok(max) });\n  }\n  if (max != null) return t('BUDGET_UP_TO', { max: formatNok(max) });\n  if (min != null) return t('BUDGET_FROM', { min: formatNok(min) });\n  return t('BUDGET_NEGOTIABLE');\n}\n\nexport function placeText(job) {\n  if (job.workType === 'remote') return t('REMOTE_WORK');\n  return job.address?.city ?? job.address?.municipality ?? t('PLACE_NOT_GIVEN');\n}\n\n// \"27 Oct\" / \"27. okt.\" in the chosen language; adds the year when it isn't this year\nexport function formatDate(iso) {\n  if (!iso) return '';\n  const d = new Date(iso);\n  const sameYear = d.getFullYear() === new Date().getFullYear();\n  try {\n    return new Intl.DateTimeFormat(currentLocale(), {\n      day: 'numeric',\n      month: 'short',\n      ...(sameYear ? {} : { year: 'numeric' }),\n    }).format(d);\n  } catch {\n    return d.toISOString().slice(0, 10);\n  }\n}\n\n// \"now\", \"5 min ago\", \"3 h ago\", \"yesterday\", then a date\nexport function timeAgo(iso) {\n  if (!iso) return '';\n  const diffMin = Math.floor((Date.now() - new Date(iso).getTime()) / 60000);\n  if (diffMin < 1) return t('TIME_NOW');\n  if (diffMin < 60) return t('TIME_MINUTES_AGO', { n: diffMin });\n  const hours = Math.floor(diffMin / 60);\n  if (hours < 24) return t('TIME_HOURS_AGO', { n: hours });\n  if (hours < 48) return t('TIME_YESTERDAY');\n  return formatDate(iso);\n}\n\n// \"14:05\" (or \"2:05 PM\") in the chosen language\nexport function formatTime(iso) {\n  if (!iso) return '';\n  const d = new Date(iso);\n  try {\n    return new Intl.DateTimeFormat(currentLocale(), { hour: 'numeric', minute: '2-digit' }).format(d);\n  } catch {\n    return d.toTimeString().slice(0, 5);\n  }\n}\n\nexport const isSameDay = (a, b) => new Date(a).toDateString() === new Date(b).toDateString();\n\n// Divider between days in a chat: \"Today\", \"Yesterday\", \"Monday\" (this week), then a date\nexport function dayLabel(iso) {\n  const d = new Date(iso);\n  const today = new Date();\n  today.setHours(0, 0, 0, 0);\n  const day = new Date(d);\n  day.setHours(0, 0, 0, 0);\n  const daysAgo = Math.round((today - day) / 86400000);\n  if (daysAgo === 0) return t('TODAY');\n  if (daysAgo === 1) return t('YESTERDAY');\n  if (daysAgo > 1 && daysAgo < 7) {\n    try {\n      return new Intl.DateTimeFormat(currentLocale(), { weekday: 'long' }).format(d);\n    } catch {\n      return formatDate(iso);\n    }\n  }\n  return formatDate(iso);\n}\n\n// Translation keys; look them up with t() when rendering\nexport const URGENCY = {\n  asap: 'URGENCY_ASAP',\n  within_week: 'URGENCY_WITHIN_WEEK',\n  within_month: 'URGENCY_WITHIN_MONTH',\n  flexible: 'URGENCY_FLEXIBLE',\n};\n\nexport const JOB_STATUS = {\n  draft: { label: 'STATUS_DRAFT', color: colors.textMuted, bg: colors.line },\n  open: { label: 'STATUS_OPEN', color: colors.pine, bg: colors.pineSoft },\n  assigned: { label: 'STATUS_ASSIGNED', color: colors.info, bg: colors.infoSoft },\n  in_progress: { label: 'STATUS_IN_PROGRESS', color: colors.amber, bg: colors.amberSoft },\n  completed: { label: 'STATUS_COMPLETED', color: colors.pine, bg: colors.pineSoft },\n  cancelled: { label: 'STATUS_CANCELLED', color: colors.danger, bg: colors.dangerSoft },\n};\n\n// Categories come from the API in Norwegian. The app translates the ones it knows by slug\n// (CAT_ELEKTRIKER, CAT_RORLEGGER_BAD, ...) and shows the API name for anything new.\nexport function categoryName(category) {\n  if (!category) return '';\n  if (category.slug) {\n    const key = `CAT_${category.slug.toUpperCase().replace(/-/g, '_')}`;\n    if (hasTranslation(key)) return t(key);\n  }\n  return category.name;\n}\n\n// Category icons from the API → valid Ionicons names (with a safe fallback)\nconst ICON_ALIASES = {\n  truck: 'car',\n  palette: 'color-palette',\n  code: 'code-slash',\n  apps: 'apps',\n};\n\nexport function categoryIcon(name) {\n  const base = ICON_ALIASES[name] ?? name ?? 'construct';\n  const outline = `${base}-outline`;\n  if (Ionicons.glyphMap[outline]) return outline;\n  if (Ionicons.glyphMap[base]) return base;\n  return 'construct-outline';\n}\n"
};

function writeFiles() {
  for (const [rel, content] of Object.entries(FILES)) {
    const file = path.join(ROOT, rel);
    const exists = fs.existsSync(file);
    if (exists && fs.readFileSync(file, 'utf8') === content) {
      console.log(`  ✔️  ${rel} (already up to date)`);
      continue;
    }
    console.log(`  ${exists ? '✏️  updated' : '➕ created'} ${rel}`);
    if (DRY) continue;
    backup(rel);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, content);
  }
}

