function updateLocales() {
  const dir = path.join(ROOT, 'src', 'locales');
  const names = fs.readdirSync(dir).filter((f) => f.endsWith('.json'));
  let changed = 0;
  for (const name of names) {
    const code = name.replace('.json', '');
    const values = TRANSLATIONS[code] ?? TRANSLATIONS['en-US'];
    if (!TRANSLATIONS[code]) console.log(`  ⚠️  ${name}: no translation, using English`);
    const file = path.join(dir, name);
    const before = fs.readFileSync(file, 'utf8');
    const data = JSON.parse(before);
    if (!('NO_MESSAGES_TEXT' in data)) {
      console.log(`  ⚠️  ${name}: has no NO_MESSAGES_TEXT, adding the new texts at the end`);
    }
    const next = {};
    let inserted = false;
    for (const [k, v] of Object.entries(data)) {
      if (NEW_KEYS.includes(k)) continue; // running twice is fine
      next[k] = v;
      if (k === 'NO_MESSAGES_TEXT') {
        NEW_KEYS.forEach((nk, i) => (next[nk] = values[i]));
        inserted = true;
      }
    }
    if (!inserted) NEW_KEYS.forEach((nk, i) => (next[nk] = values[i]));
    const after = `${JSON.stringify(next, null, '\t')}\n`;
    if (after === before) continue;
    changed++;
    if (!DRY) {
      backup(path.join('src', 'locales', name));
      fs.writeFileSync(file, after);
    }
  }
  console.log(`  🌍 ${DRY ? 'would update' : 'updated'} ${changed} of ${names.length} language files`);
}

console.log(`\n💬 Adding chat to qup-work-app${DRY ? ' (dry run, nothing is changed)' : ''}\n`);
writeFiles();
updateLocales();

if (!DRY && fs.existsSync(BACKUP)) console.log(`\n📦 Old versions saved in ${path.basename(BACKUP)}/`);
console.log(`\n✅ Done. Next: node scripts/check-locales.mjs, then npx expo start\n`);
